// Prints the source line for each tsc error that matches a pattern.
// Usage: node show.js <repo> <errors file> <regex> [maxPerGroup]
const fs = require('fs')
const path = require('path')
const [repo, errFile, pattern] = process.argv.slice(2)
const re = new RegExp(pattern)
const cache = {}
const lines = fs.readFileSync(errFile, 'utf8').split(/\r?\n/)
for (const l of lines) {
  const m = l.match(/^([^()]+)\((\d+),(\d+)\): error (TS\d+): (.*)$/)
  if (!m || !re.test(l)) continue
  const [, file, line, , code, msg] = m
  if (!cache[file]) cache[file] = fs.readFileSync(path.join(repo, file), 'utf8').split(/\r?\n/)
  const src = (cache[file][Number(line) - 1] || '').trim().slice(0, 150)
  const short = msg.replace(/import\("[^"]*[\\/]([A-Za-z]+)"\)/g, '$1').slice(0, 110)
  console.log(`${path.basename(file).replace(/Controller\.(js|ts)$/, '')}:${line} ${code} ${short}\n      ${src}`)
}

