// Audits converted controllers against the rules, from the syntax tree (comments and JSDoc are not counted as code).
// Usage: node audit.js <repo> <Name> [<Name> ...] [-v]     (Name = ApiKey, Session, ...)
const fs = require('fs')
const path = require('path')
const args = process.argv.slice(2).filter((a) => a !== '-v')
const verbose = process.argv.includes('-v')
const [repo, ...names] = args
const ts = require(path.join(repo, 'node_modules', 'typescript'))

function audit(name) {
  const file = path.join(repo, 'server', 'controllers', `${name}Controller.ts`)
  if (!fs.existsSync(file)) return null
  const text = fs.readFileSync(file, 'utf8')
  const lines = text.split(/\r?\n/)
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, true, ts.ScriptKind.TS)
  const lineOf = (node) => sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1
  const endLineOf = (node) => sf.getLineAndCharacterOfPosition(node.getEnd()).line + 1
  // a one-line comment on the same line, on the line where the statement ends, or on the line above
  const commentFor = (node) => {
    const candidates = [lineOf(node), endLineOf(node)]
    for (const l of candidates) {
      const m = (lines[l - 1] || '').match(/\/\/\s?(.*)$/)
      if (m) return m[1].trim()
    }
    const above = (lines[lineOf(node) - 2] || '').trim()
    if (above.startsWith('//')) return above.replace(/^\/\/\s?/, '')
    return null
  }
  const r = { name, lines: lines.length, nonNull: [], casts: [], any: [], oldCasts: [], indexSignatures: [], thisParams: [], banned: [], importTypes: [], references: [], exportEquals: false, declareGlobal: false }
  const skipParens = (e) => {
    while (ts.isParenthesizedExpression(e)) e = e.expression
    return e
  }
  const visit = (node) => {
    if (ts.isNonNullExpression(node)) r.nonNull.push({ line: lineOf(node), text: node.getText(sf).slice(0, 60), comment: commentFor(node) })
    if (ts.isAsExpression(node)) {
      const typeText = node.type.getText(sf)
      const inner = skipParens(node.expression)
      const double = ts.isAsExpression(inner)
      let kind = 'other'
      const comment = commentFor(node)
      const parent = node.parent && ts.isParenthesizedExpression(node.parent) ? node.parent.parent : node.parent
      const inComparison = parent && ts.isBinaryExpression(parent) && [ts.SyntaxKind.EqualsEqualsEqualsToken, ts.SyntaxKind.EqualsEqualsToken, ts.SyntaxKind.ExclamationEqualsEqualsToken, ts.SyntaxKind.ExclamationEqualsToken].includes(parent.operatorToken.kind)
      if (typeText === 'unknown' && inComparison) kind = 'A1'
      else if (typeText === 'Error') kind = 'A2'
      else if (/^Parameters<typeof /.test(typeText) || (comment && /Allowance 3/i.test(comment))) kind = 'A3'
      if (typeText === 'const') kind = 'const'
      r.casts.push({ line: lineOf(node), type: typeText.slice(0, 90), kind, double, comment })
    }
    if (node.kind === ts.SyntaxKind.AnyKeyword) r.any.push(lineOf(node))
    if (ts.isTypeAssertionExpression && ts.isTypeAssertionExpression(node)) r.oldCasts.push(lineOf(node))
    if (ts.isIndexSignatureDeclaration(node)) r.indexSignatures.push({ line: lineOf(node), text: node.getText(sf).slice(0, 60), comment: commentFor(node) })
    if (ts.isParameter(node) && ts.isIdentifier(node.name) && node.name.text === 'this') r.thisParams.push({ line: lineOf(node), type: node.type ? node.type.getText(sf) : '' })
    if (ts.isImportDeclaration(node) && node.importClause && node.importClause.isTypeOnly) r.importTypes.push(node.getText(sf))
    if (ts.isExportAssignment(node) && node.isExportEquals) r.exportEquals = node.expression.getText(sf)
    if (ts.isModuleDeclaration(node) && node.name.getText(sf) === 'global') r.declareGlobal = true
    ts.forEachChild(node, visit)
  }
  visit(sf)
  lines.forEach((l, i) => {
    if (/@ts-(ignore|nocheck|expect-error)/.test(l)) r.banned.push(i + 1)
    const m = l.match(/^\/\/\/\s*<reference path="([^"]+)"/)
    if (m) r.references.push(m[1])
  })
  return r
}

const total = { nonNull: 0, casts: { A1: 0, A2: 0, A3: 0, other: 0, const: 0 }, indexSignatures: 0, thisApiRouter: 0, thisOther: 0, any: 0, double: 0, banned: 0, uncommented: 0 }
for (const name of names) {
  const r = audit(name)
  if (!r) {
    console.log(`\n=== ${name}: no .ts file (not converted or restored)`)
    continue
  }
  const kinds = { A1: 0, A2: 0, A3: 0, other: 0, const: 0 }
  for (const c of r.casts) kinds[c.kind]++
  const doubles = r.casts.filter((c) => c.double)
  const thisApi = r.thisParams.filter((p) => p.type === 'ApiRouter').length
  // rule 5: a one-line comment each time; for the catch variable only the first use in a file needs one
  const uncommented = [...r.nonNull.filter((n) => !n.comment).map((n) => `! L${n.line}`), ...r.casts.filter((c) => !c.comment && c.kind !== 'A2' && c.kind !== 'const').map((c) => `as L${c.line}`), ...r.indexSignatures.filter((s) => !s.comment).map((s) => `[key] L${s.line}`)]
