// Groups the checkJs probe errors of the eight controllers by cause.
// Usage: node classify.js <repo> <errors file> [-v]
const fs = require('fs')
const { execSync } = require('child_process')
const [repo, errFile] = process.argv.slice(2)
const verbose = process.argv.includes('-v')
const src = {}
function line(file, n) {
  if (!src[file]) src[file] = execSync(`git show HEAD:${file}`, { cwd: repo, encoding: 'utf8', maxBuffer: 1 << 26 }).split(/\r?\n/)
  return (src[file][n - 1] || '').trim()
}
const rules = [
  ['E1 express type names required at runtime (become import type)', (e) => e.code === 'TS18042'],
  ['B1 LibraryItem.js (JS): static side is not a ModelStatic (findAll, findByPk, count, create)', (e) => e.code === 'TS2684' || (/TS2769|TS2365/.test(e.code) && /Database\.libraryItemModel\.(findAll|findByPk|count|create|findOne)/.test(e.src + ' ' + e.prev))],
  ['A  missing declaration in a converted model (mixin or field that a query adds)', (e) => /Property '(getCollectionBooks|getUser|getLibraryFolders)' does not exist/.test(e.msg) || /Property 'user' does not exist on type 'PlaybackSession'/.test(e.msg) || /'p\.libraryItem' is of type 'unknown'/.test(e.msg)],
  ['B2 LibraryItem.js (JS): media is the union BookExpanded | PodcastExpanded', (e) => /on type 'BookExpanded \| PodcastExpanded'/.test(e.msg) || (e.code === 'TS18046' && /\.media\./.test(e.msg)) || (e.code === 'TS2554' && /\.media\.changed\(/.test(e.src))],
  ['C1 converted model: method signature is narrower than the call (missing argument)', (e) => e.code === 'TS2554' && /(getOldJsonExpanded|getOldPlaylistsForUserAndLibrary)\(/.test(e.src)],
  ['C2 converted model: MediaProgress.mediaItem is the union Book | PodcastEpisode', (e) => /on type 'PodcastEpisode \| Book'/.test(e.msg)],
  ['C3 Sequelize typing narrower than the call (nested single include, where: null, order from strings)', (e) => (e.code === 'TS2769' && !/res\.download/.test(e.src)) || e.code === 'TS2353'],
  ['D1 untyped JS helper returns a union or vague type that the code reads without narrowing', (e) => /on type '\{ error: string; \} \| \{ cover: string/.test(e.msg) || /on type 'false \| /.test(e.msg) || /on type 'object'/.test(e.msg) || /on type '\{\}'/.test(e.msg) || /on type 'string \| \{ lastScan/.test(e.msg)],
  ['D2 untyped JS function: wrong parameter type (null default, required parameter, narrower JSDoc)', (e) => (e.code === 'TS2345' && !/ParsedQs|type 'this'/.test(e.msg)) || (e.code === 'TS2554' && !/\.media\.changed\(/.test(e.src))],
  ['E2 request property set by a middleware (request type)', (e) => /does not exist on type '(RequestWithUser|LibraryItemControllerRequest)'/.test(e.msg)],
  ['E3 this is the ApiRouter (erased this parameter)', (e) => /does not exist on type '[A-Za-z]+Controller'/.test(e.msg) || /Argument of type 'this'/.test(e.msg)],
  ['E4 req.query values (Request generics; TS2367 is Allowance 1)', (e) => /ParsedQs/.test(e.msg) || e.code === 'TS2367' || /TS2362|TS2363|TS2365/.test(e.code) || /Object is possibly 'undefined'/.test(e.msg)],
  ['E5 implicit any (parameter or variable needs an annotation)', (e) => /TS7006|TS7031|TS7034|TS7005/.test(e.code)],
  ['E6 possibly null or undefined (strict null checks)', (e) => /TS18047|TS18048|TS2532/.test(e.code)],
  ['E7 read or write by a dynamic key', (e) => /TS7053|TS7017/.test(e.code)],
  ['E8 property added to an object after it is built, or a variable reused with another type', (e) => e.code === 'TS2339' || e.code === 'TS2551' || e.code === 'TS2322'],
  ['E9 other (Promise without a type argument, delete of a required property, res.download callback)', () => true]
]
const counts = new Map(rules.map(([name]) => [name, { n: 0, byController: {}, items: [] }]))
let total = 0
for (const l of fs.readFileSync(errFile, 'utf8').split(/\r?\n/)) {
  const m = l.match(/^([^()]+)\((\d+),(\d+)\): error (TS\d+): (.*)$/)
  if (!m) continue
  const file = m[1]
  const n = Number(m[2])
  const e = { file, line: n, code: m[4], msg: m[5].replace(/import\("[^"]*[\\/]([A-Za-z]+)"\)/g, '$1'), src: line(file, n), prev: line(file, n - 1) }
  const c = file.replace(/^.*\/([A-Za-z]+)Controller\.js$/, '$1')
  const [name] = rules.find(([, test]) => test(e))
  const bucket = counts.get(name)
  bucket.n++
  bucket.byController[c] = (bucket.byController[c] || 0) + 1
  bucket.items.push(`${c}:${n} ${e.code} ${e.msg.slice(0, 90)}`)
  total++
}
const order = ['ApiKey', 'Session', 'User', 'Collection', 'Playlist', 'Library', 'LibraryItem', 'Podcast']
for (const [name, b] of counts) {
  console.log(`${String(b.n).padStart(4)}  ${name}   [${order.filter((c) => b.byController[c]).map((c) => `${c} ${b.byController[c]}`).join(', ')}]`)
  if (verbose) for (const i of b.items.slice(0, 400)) console.log(`        ${i}`)
}
console.log(`${String(total).padStart(4)}  total`)

