import Database = require('D:/SEM-2/574/Project/audiobookshelf-po/server/Database')

type WhereOptions = import('D:/SEM-2/574/Project/audiobookshelf-po/node_modules/sequelize').WhereOptions

export async function findAllShape(ids: string[]) {
  const libraryItems = await (Database.libraryItemModel as LibraryItemModelStatic).findAll({
    attributes: ['id', 'mediaId', 'mediaType', 'libraryId'],
    where: {
      id: ids,
      libraryId: 'lib',
      mediaType: 'book'
    },
    include: {
      model: Database.bookModel,
      attributes: ['id']
    }
  })
  return libraryItems.map((li) => li.mediaId)
}

export async function countShape(path: string) {
  return (
    (await (Database.libraryItemModel as LibraryItemModelStatic).count({
      where: {
        path
      }
    })) > 0
  )
}

export async function findByPkShape(id: string) {
  const libraryItem = await (Database.libraryItemModel as LibraryItemModelStatic).findByPk(id, {
    attributes: ['libraryId', 'mediaId']
  })
  return libraryItem?.libraryId
}

export async function createShape(t: import('D:/SEM-2/574/Project/audiobookshelf-po/node_modules/sequelize').Transaction) {
  const newLibraryItem = await (Database.libraryItemModel as LibraryItemModelStatic).create(
    {
      ino: 'x',
      path: 'p',
      isFile: false,
      mediaType: 'podcast',
      mtime: 0
    },
    { transaction: t }
  )
  return newLibraryItem.id
}

export async function nestedSingleInclude(folderId: string) {
  const libraryItemsInFolder = await (Database.libraryItemModel as LibraryItemModelStatic).findAll({
    where: {
      libraryFolderId: folderId
    },
    attributes: ['id', 'mediaId', 'mediaType'],
    include: [
      {
        model: Database.podcastModel,
        attributes: ['id'],
        include: {
          model: Database.podcastEpisodeModel,
          attributes: ['id']
        }
      },
      {
        model: Database.bookModel,
        attributes: ['id'],
        include: [
          {
            model: Database.authorModel,
            attributes: ['id'],
            through: { attributes: [] }
          }
        ]
      }
    ]
  })
  return libraryItemsInFolder.length
}

export async function collectionBooksShape(collection: import('D:/SEM-2/574/Project/audiobookshelf-po/server/models/Collection')) {
  const collectionBooks = await collection.getCollectionBooks({
    include: {
      model: Database.bookModel,
      include: Database.libraryItemModel
    },
    order: [['order', 'ASC']]
  })
  const plain = await collection.getCollectionBooks()
  return collectionBooks.length + plain.length + collectionBooks[0].order
}

