// Scratch experiment 6: LibraryController findAll (lines 188-212) and the pagination middleware (1487-1495) and line 624.
import Database = require('D:/SEM-2/574/Project/audiobookshelf-po/server/Database')
import libraryItemsBookFilters = require('D:/SEM-2/574/Project/audiobookshelf-po/server/utils/queries/libraryItemsBookFilters')
import libraryItemsPodcastFilters = require('D:/SEM-2/574/Project/audiobookshelf-po/server/utils/queries/libraryItemsPodcastFilters')

type Library = import('D:/SEM-2/574/Project/audiobookshelf-po/server/models/Library')
type LibraryStats = Awaited<ReturnType<typeof libraryItemsBookFilters.getBookLibraryStats>> | Awaited<ReturnType<typeof libraryItemsPodcastFilters.getPodcastLibraryStats>>
type OldLibraryWithStats = ReturnType<Library['toOldJSON']> & { stats?: LibraryStats }

// lib.d.ts types isNaN(number), but the built-in coerces every value. Same local declaration as MeController.ts.
declare function isNaN(value: unknown): boolean

export async function findAllShape(librariesAccessible: string[], include: string) {
  // one variable holds the models first and their old JSON later: a union annotation, narrowed by each assignment
  let libraries: Library[] | OldLibraryWithStats[] = await Database.libraryModel.getAllWithFolders()

  if (librariesAccessible.length) {
    libraries = libraries.filter((lib) => librariesAccessible.includes(lib.id))
  }

  libraries = libraries.map((lib) => lib.toOldJSON())

  const includeArray = (include || '').split(',')
  if (includeArray.includes('stats')) {
    for (const library of libraries) {
      if (library.mediaType === 'book') {
        library.stats = await libraryItemsBookFilters.getBookLibraryStats(library.id)
      } else if (library.mediaType === 'podcast') {
        library.stats = await libraryItemsPodcastFilters.getPodcastLibraryStats(library.id)
      }
    }
  }
  return { libraries }
}

// The middleware rewrites limit and page to numbers by a dynamic key.
type MiddlewareQuery = { [key: string]: string | number | undefined } // read and written by a dynamic key (queryKey)
export function middlewareShape(req: { query: MiddlewareQuery }) {
  for (const queryKey of ['limit', 'page']) {
    if (req.query[queryKey] !== undefined) {
      req.query[queryKey] = !isNaN(req.query[queryKey]) ? Number(req.query[queryKey]) : 0
      if (!Number.isInteger(req.query[queryKey]) || req.query[queryKey] < 0) {
        return `Invalid request. ${queryKey} must be a positive integer`
      }
    }
  }
  return null
}

// After the middleware, limit and page are numbers.
type HandlerQuery = { include?: string; limit?: number; page?: number; sort?: string; desc?: string; filter?: string; minified?: string; collapseseries?: string }
export function payloadShape(req: { query: HandlerQuery }, mediaType: string) {
  const include = (req.query.include || '')
    .split(',')
    .map((v) => v.trim().toLowerCase())
    .filter((v) => !!v)

  const payload: { results: object[]; total: number | undefined; limit: number; page: number; sortBy: string | undefined; sortDesc: boolean; filterBy: string | undefined; mediaType: string; minified: boolean; collapseseries: boolean; include: string; offset?: number } = {
    results: [],
    total: undefined,
    limit: req.query.limit || 0,
    page: req.query.page || 0,
    sortBy: req.query.sort,
    sortDesc: req.query.desc === '1',
    filterBy: req.query.filter,
    mediaType,
    minified: req.query.minified === '1',
    collapseseries: req.query.collapseseries === '1',
    include: include.join(',')
  }

  payload.offset = payload.page * payload.limit
  return payload
}

