// Scratch experiment 5: UserController lines 66-98 with an annotation on the query result instead of a cast.
import Database = require('D:/SEM-2/574/Project/audiobookshelf-po/server/Database')

type MediaProgress = import('D:/SEM-2/574/Project/audiobookshelf-po/server/models/MediaProgress')
type Book = import('D:/SEM-2/574/Project/audiobookshelf-po/server/models/Book')
type Podcast = import('D:/SEM-2/574/Project/audiobookshelf-po/server/models/Podcast')
type PodcastEpisode = import('D:/SEM-2/574/Project/audiobookshelf-po/server/models/PodcastEpisode')

/** What the query below loads: a book, or an episode with its podcast. A book has no podcast and an episode has no coverPath, so reading them gives undefined. */
type MediaProgressWithMediaItem = MediaProgress & { mediaItem?: (Book & { podcast?: undefined }) | (PodcastEpisode & { podcast?: Podcast; coverPath?: undefined }) }
type OldMediaProgress = ReturnType<MediaProgress['getOldMediaProgress']> & { displayTitle?: string | null; displaySubtitle?: string | null; coverPath?: string | null; mediaUpdatedAt?: Date }

export async function variantA(userId: string) {
  // the nested include is an object, not an array: does the annotation alone make the call compile? (expected: no, TS2353)
  const mediaProgresses: MediaProgressWithMediaItem[] = await Database.mediaProgressModel.findAll({
    where: {
      userId
    },
    include: [
      {
        model: Database.bookModel,
        attributes: ['id', 'title', 'coverPath', 'updatedAt']
      },
      {
        model: Database.podcastEpisodeModel,
        attributes: ['id', 'title']
      }
    ]
  })

  const oldMediaProgresses = mediaProgresses.map((mp) => {
    const oldMediaProgress: OldMediaProgress = mp.getOldMediaProgress()
    oldMediaProgress.displayTitle = mp.mediaItem?.title
    if (mp.mediaItem?.podcast) {
      oldMediaProgress.displaySubtitle = mp.mediaItem.podcast?.title
      oldMediaProgress.coverPath = mp.mediaItem.podcast?.coverPath
      oldMediaProgress.mediaUpdatedAt = mp.mediaItem.podcast?.updatedAt
    } else if (mp.mediaItem) {
      oldMediaProgress.coverPath = mp.mediaItem.coverPath
      oldMediaProgress.mediaUpdatedAt = mp.mediaItem.updatedAt
    }
    return oldMediaProgress
  })
  return oldMediaProgresses
}

export async function variantB(userId: string) {
  // the real call shape, with the nested single include, and an Allowance 3 cast of the argument
  const mediaProgresses: MediaProgressWithMediaItem[] = await Database.mediaProgressModel.findAll({
    where: {
      userId
    },
    include: [
      {
        model: Database.bookModel,
        attributes: ['id', 'title', 'coverPath', 'updatedAt']
      },
      {
        model: Database.podcastEpisodeModel,
        attributes: ['id', 'title'],
        include: {
          model: Database.podcastModel,
          attributes: ['id', 'title', 'coverPath', 'updatedAt']
        }
      }
    ]
  } as Parameters<typeof Database.mediaProgressModel.findAll>[0])
  return mediaProgresses.length
}

export async function variantC(userId: string) {
  // the real call shape without any cast (expected: TS2353 on the nested include)
  const mediaProgresses = await Database.mediaProgressModel.findAll({
    where: {
      userId
    },
    include: [
      {
        model: Database.bookModel,
        attributes: ['id', 'title', 'coverPath', 'updatedAt']
      },
      {
        model: Database.podcastEpisodeModel,
        attributes: ['id', 'title'],
        include: {
          model: Database.podcastModel,
          attributes: ['id', 'title', 'coverPath', 'updatedAt']
        }
      }
    ]
  })
  return mediaProgresses.length
}

