// Per-file behaviour pre-check, without a build: transpiles one converted controller (types erased, nothing else)
// and compares its statements with the baseline compiled file. Require lines may differ; code may not.
// Usage: node precheck.js <repo> <baseline> <Name> [<Name> ...] [-v]     (Name = ApiKey, Session, ...)
const fs = require('fs')
const path = require('path')
const args = process.argv.slice(2).filter((a) => a !== '-v')
const verbose = process.argv.includes('-v')
const [repo, baseline, ...names] = args
const ts = require(path.join(repo, 'node_modules', 'typescript'))
const printer = ts.createPrinter({ removeComments: true, newLine: ts.NewLineKind.LineFeed })

function hasRequireCall(node) {
  let found = false
  const visit = (n) => {
    if (found) return
    if (ts.isCallExpression(n) && ts.isIdentifier(n.expression) && n.expression.text === 'require') {
      found = true
      return
    }
    if (ts.isFunctionLike(n)) return
    ts.forEachChild(n, visit)
  }
  visit(node)
  return found
}

function split(fileName, text) {
  const sf = ts.createSourceFile(fileName, text, ts.ScriptTarget.ES2022, true, ts.ScriptKind.JS)
  const requires = []
  const code = []
  const requireNames = new Set()
  for (const stmt of sf.statements) {
    const printed = printer.printNode(ts.EmitHint.Unspecified, stmt, sf)
    if (ts.isVariableStatement(stmt)) {
      const decls = stmt.declarationList.declarations
      if (decls.every((d) => d.initializer && hasRequireCall(d.initializer))) {
        requires.push(printed)
        for (const d of decls) if (ts.isIdentifier(d.name)) requireNames.add(d.name.text)
        continue
      }
      if (decls.every((d) => ts.isObjectBindingPattern(d.name) && d.initializer && ts.isIdentifier(d.initializer) && requireNames.has(d.initializer.text))) {
        requires.push(printed)
        continue
      }
    }
    code.push(printed)
  }
  return { requires, code }
}

let bad = 0
for (const name of names) {
  const tsFile = path.join(repo, 'server', 'controllers', `${name}Controller.ts`)
  const baseFile = path.join(baseline, 'server', 'controllers', `${name}Controller.js`)
  if (!fs.existsSync(tsFile)) {
    console.log(`${name}: no .ts file (not converted or restored)`)
    continue
  }
  const out = ts.transpileModule(fs.readFileSync(tsFile, 'utf8'), {
    fileName: tsFile,
    compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.CommonJS, esModuleInterop: true, strict: true }
  })
  const a = split(baseFile, fs.readFileSync(baseFile, 'utf8'))
  const b = split(tsFile.replace(/\.ts$/, '.js'), out.outputText)
  const same = a.code.length === b.code.length && a.code.every((s, i) => s === b.code[i])
  if (same) {
    console.log(`${name}: CODE IDENTICAL (${a.code.length} statements; require lines: baseline ${a.requires.length}, now ${b.requires.length})`)
  } else {
    bad++
    console.log(`${name}: CODE DIFFERS (statements: baseline ${a.code.length}, now ${b.code.length})`)
    const max = Math.max(a.code.length, b.code.length)
    let shown = 0
    for (let i = 0; i < max && shown < 4; i++) {
      if (a.code[i] === b.code[i]) continue
      shown++
      const la = (a.code[i] || '<none>').split('\n')
      const lb = (b.code[i] || '<none>').split('\n')
      let printedLines = 0
      // simple line walk; good enough when lines were changed in place
      for (let j = 0; j < Math.max(la.length, lb.length) && printedLines < 14; j++) {
        if (la[j] !== lb[j]) {
          printedLines++
          console.log(`   stmt ${i} line ${j}\n     - ${la[j]}\n     + ${lb[j]}`)
        }
      }
    }
  }
  if (verbose) {
    const setA = new Set(a.requires)
    const setB = new Set(b.requires)
    for (const r of a.requires) if (!setB.has(r)) console.log(`     - ${r}`)
    for (const r of b.requires) if (!setA.has(r)) console.log(`     + ${r}`)
  }
}
process.exit(bad ? 1 : 0)

