// Compares dist-server with the baseline copy. Comments and require lines may differ; code may not.
// Usage: node compare.js <repo> <baseline> [-v]
const fs = require('fs')
const path = require('path')
const repo = process.argv[2]
const baseline = process.argv[3]
const verbose = process.argv.includes('-v')
const ts = require(path.join(repo, 'node_modules', 'typescript'))

function walk(dir, base, out) {
  for (const name of fs.readdirSync(dir)) {
    const full = path.join(dir, name)
    const st = fs.statSync(full)
    if (st.isDirectory()) walk(full, base, out)
    else if (name.endsWith('.js')) out.add(path.relative(base, full).replace(/\\/g, '/'))
  }
  return out
}

const printer = ts.createPrinter({ removeComments: true, newLine: ts.NewLineKind.LineFeed })

function hasRequireCall(node) {
  let found = false
  const visit = (n) => {
    if (found) return
    if (ts.isCallExpression(n) && ts.isIdentifier(n.expression) && n.expression.text === 'require') {
      found = true
      return
    }
    // do not look inside function bodies: a lazy require inside a function is code
    if (ts.isFunctionLike(n)) return
    ts.forEachChild(n, visit)
  }
  visit(node)
  return found
}

// Splits the top-level statements of a compiled file into require statements and code statements.
function split(file) {
  const text = fs.readFileSync(file, 'utf8')
  const sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, true, ts.ScriptKind.JS)
  const requires = []
  const code = []
  const requireNames = new Set()
  for (const stmt of sf.statements) {
    const printed = printer.printNode(ts.EmitHint.Unspecified, stmt, sf)
    if (ts.isVariableStatement(stmt)) {
      const decls = stmt.declarationList.declarations
      if (decls.every((d) => d.initializer && hasRequireCall(d.initializer))) {
        requires.push(printed)
        for (const d of decls) if (ts.isIdentifier(d.name)) requireNames.add(d.name.text)
        continue
      }
      // `const { a, b } = x` where x was bound by a require: the second half of a split destructured require
      if (decls.every((d) => ts.isObjectBindingPattern(d.name) && d.initializer && ts.isIdentifier(d.initializer) && requireNames.has(d.initializer.text))) {
        requires.push(printed)
        continue
      }
    }
    code.push(printed)
  }
  return { requires, code }
}

const a = walk(baseline, baseline, new Set())
const b = walk(path.join(repo, 'dist-server'), path.join(repo, 'dist-server'), new Set())
const onlyA = [...a].filter((f) => !b.has(f)).sort()
const onlyB = [...b].filter((f) => !a.has(f)).sort()
let codeDiffFiles = 0
let requireDiffFiles = 0
let rawDiffFiles = 0
for (const f of [...a].filter((x) => b.has(x)).sort()) {
  const fa = path.join(baseline, f)
  const fb = path.join(repo, 'dist-server', f)
  const ra = fs.readFileSync(fa, 'utf8')
  const rb = fs.readFileSync(fb, 'utf8')
  if (ra === rb) continue
  rawDiffFiles++
  const sa = split(fa)
  const sb = split(fb)
  const codeSame = sa.code.length === sb.code.length && sa.code.every((s, i) => s === sb.code[i])
  const reqSame = sa.requires.join('\n') === sb.requires.join('\n')
  if (!codeSame) {
    codeDiffFiles++
    console.log(`CODE DIFF  ${f}`)
    const max = Math.max(sa.code.length, sb.code.length)
    let shown = 0
    for (let i = 0; i < max && shown < 6; i++) {
      if (sa.code[i] !== sb.code[i]) {
        shown++
        const la = (sa.code[i] || '<none>').split('\n')
        const lb = (sb.code[i] || '<none>').split('\n')
        const lines = Math.max(la.length, lb.length)
        let printedLines = 0
        for (let j = 0; j < lines && printedLines < 12; j++) {
          if (la[j] !== lb[j]) {
            printedLines++
            console.log(`   stmt ${i} line ${j}\n     - ${la[j]}\n     + ${lb[j]}`)
          }
        }
      }
    }
  } else if (!reqSame) {
    requireDiffFiles++
    console.log(`require-only diff  ${f}`)
    if (verbose) {
      const setA = new Set(sa.requires)
      const setB = new Set(sb.requires)
      for (const r of sa.requires) if (!setB.has(r)) console.log(`     - ${r}`)
      for (const r of sb.requires) if (!setA.has(r)) console.log(`     + ${r}`)
    }
  } else {
    console.log(`comment/whitespace-only diff  ${f}`)
  }
}
for (const f of onlyA) console.log(`ONLY IN BASELINE  ${f}`)
for (const f of onlyB) console.log(`ONLY IN DIST  ${f}`)
console.log(`\nfiles: baseline ${a.size}, dist ${b.size}; raw-different ${rawDiffFiles}; code-different ${codeDiffFiles}; require-only ${requireDiffFiles}; only-baseline ${onlyA.length}; only-dist ${onlyB.length}`)
process.exit(codeDiffFiles || onlyA.length || onlyB.length ? 1 : 0)

